"""GENERATED by scripts/update_cloudflare_ips.py — edit that, not this.

Cloudflare's edge ranges. An address in them is Cloudflare, never a player:
nginx resolves the real visitor IP (nginx/*/cloudflare-realip.conf.template),
and the fraud engine ignores any Cloudflare address recorded before that.
"""
import ipaddress
from functools import lru_cache

CLOUDFLARE_RANGES = (
    '173.245.48.0/20',
    '103.21.244.0/22',
    '103.22.200.0/22',
    '103.31.4.0/22',
    '141.101.64.0/18',
    '108.162.192.0/18',
    '190.93.240.0/20',
    '188.114.96.0/20',
    '197.234.240.0/22',
    '198.41.128.0/17',
    '162.158.0.0/15',
    '104.16.0.0/13',
    '104.24.0.0/14',
    '172.64.0.0/13',
    '131.0.72.0/22',
    '2400:cb00::/32',
    '2606:4700::/32',
    '2803:f800::/32',
    '2405:b500::/32',
    '2405:8100::/32',
    '2a06:98c0::/29',
    '2c0f:f248::/32',
)


@lru_cache(maxsize=1)
def _networks():
    return tuple(ipaddress.ip_network(r) for r in CLOUDFLARE_RANGES)


def is_cloudflare(ip) -> bool:
    try:
        addr = ipaddress.ip_address(str(ip))
    except ValueError:
        return False
    return any(addr in net for net in _networks() if net.version == addr.version)
